code='''def transform(grid):
    out=[row[:] for row in grid]
    h,w=len(grid),len(grid[0])
    centers=[]
    for r in range(1,h-1):
        for c in range(1,w-1):
            if grid[r-1][c]==grid[r+1][c]==grid[r][c-1]==grid[r][c+1]==2 and grid[r][c]==0:
                centers.append((r,c))
    for i,(r,c) in enumerate(centers):
        for rr,cc in centers[i+1:]:
            if r==rr:
                for x in range(min(c,cc)+2,max(c,cc)-1):
                    if out[r][x]==0: out[r][x]=1
            elif c==cc:
                for y in range(min(r,rr)+2,max(r,rr)-1):
                    if out[y][c]==0: out[y][c]=1
    return out
'''
